#include <cstdio>
#include <vector>

int main() {
    int n, k;

    while (scanf("%d%d", &n, &k) == 2) {
        std::vector<int> a(n);

        for (int i = 0; i < n; ++i) {
            scanf("%d", &a[i]);
        }

        int num = 0;
        while (num < n && a[num] <= k) {
            ++num;
        }

        int sum = num;
        for (int i = n - 1; i >= num && a[i] <= k; --i) {
            ++sum;
        }

        printf("%d\n", sum);
    }

    return 0;
}

