#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    while (cin >> n >> k) {
        vector<int> a(n);
        for (int& x : a) cin >> x;

        int left = 0;
        while (left < n && a[left] <= k) ++left;

        int right = n - 1;
        while (right >= left && a[right] <= k) --right;

        cout << left + (n - 1 - right) << '\n';
    }

    return 0;
}

